.mc-story-deck{overflow:visible}.mc-story-deck-head{margin-bottom:24px}.mc-story-workbench{display:grid;grid-template-columns:minmax(0,1fr) 330px;gap:28px;align-items:start}.mc-story-canvas{min-width:0}.mc-story-canvas .chapter-preview{width:min(100%,560px);margin:0 auto;min-height:0;height:auto;display:flex;flex-direction:column;justify-content:flex-end;transition:aspect-ratio .28s ease,border-radius .28s ease,box-shadow .28s ease}.mc-story-canvas .chapter-preview[data-preset="vertical"]{aspect-ratio:9/16;max-height:660px}.mc-story-canvas .chapter-preview[data-preset="portrait"]{aspect-ratio:4/5;max-height:620px}.mc-story-canvas .chapter-preview[data-preset="square"]{aspect-ratio:1/1;max-height:560px}.mc-story-canvas .chapter-nav{margin-top:18px}.mc-story-privacy-badge{display:inline-flex;align-self:flex-start;margin-top:20px;padding:8px 11px;border-radius:999px;font:800 10px/1.2 ui-monospace,SFMono-Regular,Menlo,monospace;letter-spacing:.055em;text-transform:uppercase;border:1px solid currentColor;backdrop-filter:blur(10px)}.mc-story-privacy-badge.is-safe{opacity:.78}.mc-story-privacy-badge.is-sensitive{background:rgba(251,113,133,.12);color:#ffe4e9}

/* Art-directed theme selector */
.mc-theme-selector{border:0;padding:0;margin:0;min-width:0;position:sticky;top:98px}.mc-theme-selector>legend{font-family:var(--mc-display);font-size:27px;letter-spacing:-.035em;padding:0;margin:0 0 8px}.mc-theme-selector>p{margin:0 0 16px;color:var(--mc-muted);font-size:12px;line-height:1.55}.mc-theme-carousel{display:grid;grid-template-columns:1fr;gap:10px}.mc-theme-card{appearance:none;width:100%;min-height:96px;border:1px solid var(--mc-line);border-radius:20px;padding:9px;background:rgba(255,255,255,.64);display:grid;grid-template-columns:80px 1fr;gap:12px;text-align:left;cursor:pointer;color:var(--mc-ink);transition:transform .18s ease,border-color .18s ease,box-shadow .18s ease,background .18s ease}.mc-theme-card:hover{transform:translateY(-2px);border-color:rgba(77,58,112,.28)}.mc-theme-card.is-selected{background:#fff;border-color:#6d56bd;box-shadow:0 14px 34px rgba(66,49,97,.13)}.mc-theme-card.is-locked{opacity:.72}.mc-theme-swatch{height:76px;border-radius:14px;position:relative;overflow:hidden;display:block;border:1px solid rgba(255,255,255,.14)}.mc-theme-swatch:before{content:"Aa";position:absolute;left:10px;bottom:9px;font:600 25px/1 var(--mc-display)}.mc-theme-swatch i{position:absolute;right:9px;top:9px;width:11px;height:11px;border-radius:50%;box-shadow:0 0 0 6px rgba(255,255,255,.08)}.mc-theme-copy{min-width:0;display:flex;flex-direction:column;justify-content:center;gap:5px}.mc-theme-copy>span{display:flex;align-items:center;justify-content:space-between;gap:8px}.mc-theme-copy strong{font-size:14px}.mc-theme-copy em{font-style:normal;font:800 9px/1 ui-monospace,monospace;text-transform:uppercase;letter-spacing:.07em;padding:5px 7px;border-radius:999px;background:#eee9f8;color:#654e9b}.mc-theme-copy small{color:var(--mc-muted);font-size:10px;line-height:1.35}

/* Export toolbar */
.mc-export-toolbar{margin-top:28px;border:1px solid var(--mc-line);border-radius:26px;background:rgba(255,253,248,.94);box-shadow:0 20px 55px rgba(38,29,52,.1);padding:16px;display:grid;gap:14px;backdrop-filter:blur(22px)}.mc-export-toolbar-head{display:flex;justify-content:space-between;gap:14px;align-items:center}.mc-export-toolbar-head strong,.mc-export-toolbar-head small{display:block}.mc-export-toolbar-head strong{font-family:var(--mc-display);font-size:20px;font-weight:500}.mc-export-toolbar-head small{color:var(--mc-muted);font-size:10px;margin-top:3px}.mc-local-badge{flex:none;border-radius:999px;padding:7px 9px;background:#e5f8ef;color:#176644;font:850 9px/1 ui-monospace,monospace;letter-spacing:.07em;text-transform:uppercase}.mc-format-picker{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}.mc-format-picker button{min-height:58px;border:1px solid var(--mc-line);border-radius:16px;background:#fff;padding:9px 11px;text-align:left;color:var(--mc-ink);cursor:pointer}.mc-format-picker button.is-selected{border-color:#745bb4;background:#f0ebff;box-shadow:inset 0 0 0 1px #745bb4}.mc-format-picker strong,.mc-format-picker small{display:block}.mc-format-picker strong{font-size:11px}.mc-format-picker small{font-size:9px;color:var(--mc-muted);margin-top:3px}.mc-export-actions{display:grid;grid-template-columns:1.15fr .85fr 1.15fr;gap:8px}.mc-export-actions .btn{width:100%}.mc-export-status{margin-top:12px}

/* Keepsake */
.mc-keepsake{background:linear-gradient(145deg,#f7f1e8,#fffdf8);border-color:rgba(139,94,52,.14)}.mc-keepsake-intro{max-width:760px}.mc-keepsake-intro h3{font-family:var(--mc-display);font-size:clamp(34px,4vw,54px);font-weight:500;line-height:1.02;letter-spacing:-.045em;margin:9px 0 14px}.mc-keepsake-intro p{color:#76695d;line-height:1.65}.mc-keepsake-steps{display:grid;grid-template-columns:repeat(3,1fr);margin:28px 0;border-top:1px solid rgba(139,94,52,.16);border-bottom:1px solid rgba(139,94,52,.16)}.mc-keepsake-steps button{appearance:none;border:0;border-right:1px solid rgba(139,94,52,.16);background:transparent;min-height:92px;padding:14px;text-align:left;display:grid;grid-template-columns:24px 1fr;grid-template-rows:auto auto;align-content:center;color:#76695d;cursor:pointer}.mc-keepsake-steps button:last-child{border-right:0}.mc-keepsake-steps button>span{grid-row:1/3;font:800 10px ui-monospace,monospace}.mc-keepsake-steps strong{font-family:var(--mc-display);font-size:18px;font-weight:500;color:#3b2d23}.mc-keepsake-steps small{font-size:9px}.mc-keepsake-steps button.is-active{background:#fffaf2}.mc-keepsake-workspace{display:grid;grid-template-columns:minmax(0,.82fr) minmax(380px,1.18fr);gap:34px;align-items:start}.mc-keepsake-editor{display:grid;gap:18px}.mc-keepsake-step{display:grid;gap:14px;background:rgba(255,253,248,.74);border:1px solid rgba(139,94,52,.14);border-radius:24px;padding:22px}.mc-keepsake-step h4{font-family:var(--mc-display);font-weight:500;font-size:24px;line-height:1.08;margin:0}.mc-keepsake-step label{display:grid;gap:7px;font-size:11px;font-weight:800}.mc-step-kicker{font:800 9px ui-monospace,monospace;text-transform:uppercase;letter-spacing:.08em;color:#8b5e34}.mc-keepsake-note{background:#efe2cf;border-radius:17px;padding:14px;color:#5c4939}.mc-keepsake-note strong{font-size:11px}.mc-keepsake-note p{font-size:10px;line-height:1.5;margin:4px 0 0}.mc-mobile-next{display:none}.mc-book-preview{position:sticky;top:98px;border-radius:28px;background:#2d231d;padding:20px;color:#f7f1e8;box-shadow:0 32px 75px rgba(55,38,25,.2)}.mc-book-stage{min-height:390px;display:flex;align-items:center;justify-content:center;position:relative;perspective:1200px;padding:18px 30px}.mc-book-cover{width:min(68%,290px);aspect-ratio:6/9;border-radius:4px 14px 14px 4px;background:linear-gradient(145deg,#f7f1e8,#e6d2b4);color:#2d231d;padding:24px;box-shadow:-10px 14px 0 #c9ae89,0 28px 60px rgba(0,0,0,.32);display:flex;flex-direction:column;justify-content:space-between;transform:rotateY(-8deg) rotateZ(-1deg);transform-origin:left center}.mc-book-cover small,.mc-book-cover>span{font:800 8px ui-monospace,monospace;letter-spacing:.06em;text-transform:uppercase;color:#76695d}.mc-book-cover h3{font-family:var(--mc-display);font-size:31px;line-height:1;letter-spacing:-.04em;margin:0}.mc-book-cover p{font-size:10px;color:#76695d}.mc-book-page-peek{position:absolute;right:18px;bottom:28px;width:42%;min-height:160px;background:#fffdf8;color:#3b2d23;border-radius:4px 10px 10px 4px;padding:18px;box-shadow:0 18px 45px rgba(0,0,0,.18);transform:rotate(4deg)}.mc-book-page-peek small{font:800 8px ui-monospace,monospace;text-transform:uppercase;color:#8b5e34}.mc-book-page-peek p{font-family:var(--mc-display);font-size:13px;line-height:1.35}.mc-book-meta{display:grid;grid-template-columns:repeat(3,1fr);border-top:1px solid rgba(255,255,255,.12);border-bottom:1px solid rgba(255,255,255,.12)}.mc-book-meta div{padding:13px;border-right:1px solid rgba(255,255,255,.12)}.mc-book-meta div:last-child{border-right:0}.mc-book-meta strong,.mc-book-meta span{display:block}.mc-book-meta strong{font-family:var(--mc-display);font-size:20px;font-weight:500}.mc-book-meta span{font-size:8px;opacity:.6;text-transform:uppercase}.mc-page-map{list-style:none;margin:14px 0;padding:0;display:grid;gap:0}.mc-page-map li{display:flex;gap:11px;padding:8px 0;border-bottom:1px solid rgba(255,255,255,.08)}.mc-page-map li>span{font:800 8px ui-monospace,monospace;opacity:.5;padding-top:2px}.mc-page-map strong,.mc-page-map small{display:block}.mc-page-map strong{font-size:10px}.mc-page-map small{font-size:8px;opacity:.5}.mc-print-action{width:100%;background:#f7f1e8;color:#2d231d}.mc-print-disclaimer{display:block;text-align:center;margin-top:8px;opacity:.55;font-size:8px}.print-book{display:none}

/* Product builders: editorial instead of dashboard blocks */
.product-builder[data-product="myyear"] .product-workspace,.product-builder[data-product="petlife"] .product-workspace{background:linear-gradient(180deg,rgba(255,253,248,.98),rgba(247,241,232,.92));border-color:rgba(49,87,44,.1)}.product-builder .builder-card{border-radius:24px}.product-builder .timeline-list article{border-radius:20px}.product-builder .local-media-grid figure{overflow:hidden;border-radius:16px}.product-builder .chapter-preview{box-shadow:0 28px 75px rgba(45,32,59,.16)}

/* Tablet is intentionally composed, not stretched mobile. */
@media (min-width:768px) and (max-width:1100px){
  .shell{width:min(100% - 44px,1020px)}
  .mc-story-workbench{grid-template-columns:minmax(0,1fr) 280px;gap:20px}.mc-theme-selector{top:88px}.mc-theme-card{grid-template-columns:64px 1fr}.mc-theme-swatch{height:64px}.mc-export-toolbar{grid-template-columns:1fr;position:sticky;bottom:14px;z-index:45}.mc-export-actions{grid-template-columns:repeat(3,1fr)}
  .mc-keepsake-workspace{grid-template-columns:minmax(0,.9fr) minmax(340px,1.1fr);gap:22px}.mc-book-preview{top:88px}.mc-book-stage{min-height:340px;padding-inline:15px}.mc-book-cover{width:70%}
  .product-builder[data-product="myyear"] .product-workspace{display:grid;grid-template-columns:minmax(0,.9fr) minmax(0,1.1fr);gap:18px}.product-builder[data-product="myyear"] .product-workspace>.chapter-head{grid-column:1/-1}.product-builder[data-product="myyear"] .product-workspace>.builder-grid,.product-builder[data-product="myyear"] .product-workspace>.builder-card{grid-column:1}.product-builder[data-product="myyear"] .product-workspace>.timeline-list{grid-column:2;grid-row:2/span 3;margin-top:0;align-self:start;max-height:720px;overflow:auto;padding-right:4px}
}

/* Phones: social-story first, thumb-friendly, no horizontal overflow. */
@media (max-width:767px){
  .shell{width:min(100% - 28px,680px)}.btn,button,.select,.share-input{min-height:var(--mc-os-touch)}
  .mc-story-workbench{display:block}.mc-story-canvas .chapter-preview{width:100%;max-height:none;border-radius:28px}.mc-story-canvas .chapter-nav{display:grid;grid-template-columns:auto 1fr auto;gap:7px;align-items:center}.mc-story-canvas .chapter-nav .btn{padding-inline:13px;min-width:0}.chapter-dots{overflow-x:auto;justify-content:flex-start;scrollbar-width:none;padding:10px 4px}.chapter-dots::-webkit-scrollbar{display:none}
  .mc-theme-selector{position:static;margin-top:26px}.mc-theme-selector>legend{font-size:24px}.mc-theme-carousel{display:flex;overflow-x:auto;scroll-snap-type:x mandatory;gap:10px;margin-inline:-14px;padding:2px 14px 12px;scrollbar-width:none}.mc-theme-carousel::-webkit-scrollbar{display:none}.mc-theme-card{flex:0 0:min(82vw,300px);scroll-snap-align:center;grid-template-columns:76px 1fr}
  .mc-export-toolbar{position:sticky;bottom:max(8px,var(--mc-os-safe));z-index:55;margin:20px -7px 0;padding:12px;border-radius:22px;box-shadow:0 18px 60px rgba(28,20,39,.24)}.mc-export-toolbar-head{align-items:flex-start}.mc-format-picker{display:flex;overflow-x:auto;scroll-snap-type:x mandatory;scrollbar-width:none}.mc-format-picker::-webkit-scrollbar{display:none}.mc-format-picker button{flex:0 0:42%;scroll-snap-align:start}.mc-export-actions{grid-template-columns:1fr 1fr}.mc-export-actions .btn:last-child{grid-column:1/-1}.mc-export-status{margin-bottom:12px}
  .mc-keepsake{padding-inline:16px}.mc-keepsake-steps{grid-template-columns:1fr;margin-inline:-16px}.mc-keepsake-steps button{min-height:62px;border-right:0;border-bottom:1px solid rgba(139,94,52,.14);grid-template-columns:22px 1fr}.mc-keepsake-steps button:last-child{border-bottom:0}.mc-keepsake-steps small{display:none}.mc-keepsake-workspace{display:block}.mc-keepsake-step{display:none;padding:18px}.mc-keepsake-step.is-active{display:grid}.mc-mobile-next{display:inline-flex}.mc-book-preview{display:none;position:static;margin-top:0}.mc-book-preview.is-active{display:block}.mc-book-stage{min-height:330px;padding:8px}.mc-book-cover{width:72%;padding:18px}.mc-book-cover h3{font-size:26px}.mc-book-page-peek{right:2px;bottom:14px;width:46%;min-height:130px;padding:13px}.mc-book-meta{grid-template-columns:1fr}.mc-book-meta div{border-right:0;border-bottom:1px solid rgba(255,255,255,.1)}.mc-book-meta div:last-child{border-bottom:0}
  .product-builder .builder-grid{grid-template-columns:1fr!important}.product-builder .premium-actions{display:grid;grid-template-columns:1fr}.product-builder .premium-actions .btn{width:100%}.product-builder .timeline-list article{align-items:flex-start}
}

@media (max-width:430px){.mc-story-deck{padding-inline:14px}.mc-export-toolbar-head small{max-width:220px}.mc-local-badge{display:none}.mc-format-picker button{flex-basis:48%}.mc-theme-card{flex-basis:86vw}.mc-book-cover{width:78%}}
@media (max-width:375px){.mc-format-picker button{flex-basis:54%}.mc-theme-card{flex-basis:88vw}.mc-story-canvas .chapter-nav .btn{font-size:10px;padding-inline:10px}}
@media (max-width:360px){.mc-export-actions{grid-template-columns:1fr}.mc-export-actions .btn:last-child{grid-column:auto}.mc-book-cover{width:82%}.mc-book-page-peek{width:49%}}

@media (min-width:1180px){.mc-story-workbench{grid-template-columns:minmax(0,1fr) 360px;gap:42px}.mc-theme-card{grid-template-columns:86px 1fr}.mc-keepsake-workspace{grid-template-columns:minmax(0,.78fr) minmax(430px,1.22fr);gap:46px}}
@media (min-width:1440px){.shell{width:min(1280px,calc(100% - 64px))}.mc-story-workbench{grid-template-columns:minmax(0,1fr) 390px}.mc-story-canvas .chapter-preview{max-height:720px}.mc-keepsake-workspace{gap:58px}}
@media (min-width:1728px){.shell{width:min(1380px,calc(100% - 96px))}.mc-story-workbench{grid-template-columns:minmax(0,1fr) 420px}.mc-theme-selector>legend{font-size:30px}}

@media(prefers-reduced-motion:reduce){.mc-theme-card,.mc-story-canvas .chapter-preview{transition:none!important}.mc-theme-card:hover{transform:none}.mc-book-cover,.mc-book-page-peek{transform:none}}

@media print{.mc-keepsake-intro,.mc-keepsake-steps,.mc-keepsake-workspace{display:none!important}.print-book{display:block!important}.print-page{break-after:page;min-height:90vh;padding:10vh 10vw;background:#fff;color:#241c15}.print-page h1,.print-page h2{font-family:Georgia,"Times New Roman",serif}.print-page-cover{display:grid;place-content:center;text-align:center}}

/* Memory Cinema — consumer storytelling UI layer. Loaded last so product logic stays untouched. */
:root{
  --mc-bg:#f4efe7;--mc-paper:#fffdf8;--mc-ink:#17141f;--mc-muted:#716b78;--mc-line:rgba(23,20,31,.11);
  --mc-midnight:#080a12;--mc-midnight-2:#111426;--mc-violet:#a78bfa;--mc-sky:#38bdf8;--mc-rose:#fb7185;
  --mc-orange:#f97316;--mc-pink:#ec4899;--mc-green:#31572c;--mc-shadow:0 28px 90px rgba(29,22,43,.13);
  --mc-display:Georgia,"Times New Roman",serif;--mc-ui:Inter,Geist,ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;
}
html{scroll-padding-top:90px}body{background:var(--mc-bg);color:var(--mc-ink);font-family:var(--mc-ui);overflow-x:hidden}.shell{width:min(1180px,calc(100% - 40px))}
::selection{background:#d9cffc;color:#17141f}button:focus-visible,a:focus-visible,input:focus-visible,select:focus-visible,textarea:focus-visible{outline:3px solid #8b5cf6;outline-offset:3px}

/* Navigation */
.mc-nav-shell{position:sticky;top:0;z-index:80;background:rgba(244,239,231,.84);backdrop-filter:blur(22px);border-bottom:1px solid rgba(23,20,31,.06)}
.mc-nav{min-height:76px;padding:14px 0}.mc-nav .brand{font-size:19px}.mc-nav .brand-mark,.mc-footer .brand-mark{background:var(--mc-midnight);border:1px solid rgba(255,255,255,.12);box-shadow:0 8px 26px rgba(8,10,18,.18)}
.mc-navlinks{gap:26px}.mc-navlinks>a:not(.btn){position:relative;color:#5e5964}.mc-navlinks>a:not(.btn):after{content:"";position:absolute;left:0;right:100%;bottom:-7px;height:2px;background:#17141f;transition:right .2s ease}.mc-navlinks>a:not(.btn):hover:after{right:0}
.mc-menu-button{display:none;width:46px;height:46px;border-radius:16px;border:1px solid var(--mc-line);background:var(--mc-paper);align-items:center;justify-content:center;flex-direction:column;gap:6px}.mc-menu-button span{display:block;width:19px;height:2px;background:var(--mc-ink);border-radius:4px}
.btn{min-height:44px;border-radius:999px;letter-spacing:-.01em}.btn-primary{background:var(--mc-midnight);box-shadow:0 14px 34px rgba(8,10,18,.18)}.btn-primary:hover{box-shadow:0 18px 42px rgba(8,10,18,.24)}.btn-soft{background:rgba(255,255,255,.74);border-color:var(--mc-line);backdrop-filter:blur(12px)}

/* Landing hero */
.mc-hero-wrap{position:relative;background:radial-gradient(circle at 12% 20%,rgba(167,139,250,.2),transparent 30%),radial-gradient(circle at 88% 30%,rgba(56,189,248,.14),transparent 28%),linear-gradient(145deg,#070810,#0e1020 58%,#17142b);color:#fff;overflow:hidden;border-radius:0 0 52px 52px}
.mc-hero-wrap:before{content:"";position:absolute;inset:0;opacity:.28;background-image:radial-gradient(rgba(255,255,255,.2) .7px,transparent .7px);background-size:24px 24px;mask-image:linear-gradient(to bottom,#000,transparent 82%)}
.mc-hero{position:relative;z-index:1;min-height:760px;padding:96px 0 84px;display:grid;grid-template-columns:minmax(0,1.04fr) minmax(420px,.96fr);align-items:center;gap:50px}.mc-hero-copy{max-width:670px}.mc-eyebrow{display:inline-flex;align-items:center;gap:9px;padding:9px 13px;border:1px solid rgba(255,255,255,.16);border-radius:999px;background:rgba(255,255,255,.06);font-size:12px;font-weight:850;letter-spacing:.05em;color:#d8d7e7}.mc-eyebrow i{width:7px;height:7px;border-radius:50%;background:#66e3b4;box-shadow:0 0 0 5px rgba(102,227,180,.11)}.mc-eyebrow.dark{color:#5e5865;background:rgba(255,255,255,.68);border-color:var(--mc-line)}
.mc-hero h1{font-family:var(--mc-display);font-size:clamp(60px,6.6vw,96px);font-weight:500;line-height:.91;letter-spacing:-.065em;margin:28px 0 26px}.mc-hero h1 em,.mc-section-heading h2 em,.mc-create-head h1 em{font-weight:500;color:#c9b8ff}.mc-hero p{font-size:19px;line-height:1.72;color:#b7b8c8;max-width:620px}.mc-hero-actions{justify-content:flex-start;margin-top:34px}.mc-hero-actions .btn-primary{background:#fff;color:#11131c;box-shadow:0 16px 46px rgba(0,0,0,.25)}.mc-hero-actions .btn-soft{background:rgba(255,255,255,.08);border-color:rgba(255,255,255,.15);color:#fff}.mc-trust-row{display:flex;flex-wrap:wrap;gap:9px 18px;margin-top:25px;color:#9295a9;font-size:12px;font-weight:750}
.mc-preview-stage{position:relative;min-height:560px;perspective:1100px}.mc-orbit{position:absolute;border:1px solid rgba(255,255,255,.08);border-radius:50%}.mc-orbit-one{width:520px;height:520px;right:-40px;top:15px}.mc-orbit-two{width:390px;height:390px;right:25px;top:80px}.mc-preview-card{position:absolute;border-radius:28px;padding:24px;border:1px solid rgba(255,255,255,.12);box-shadow:0 34px 90px rgba(0,0,0,.32);backdrop-filter:blur(24px);transform-style:preserve-3d}.mc-preview-card small{display:block;text-transform:uppercase;letter-spacing:.14em;font-size:10px;font-weight:850;opacity:.62}.mc-preview-card strong{font-family:var(--mc-display);font-weight:500;letter-spacing:-.06em}.mc-preview-card span{font-size:12px;opacity:.72}.mc-preview-main{inset:65px 30px 65px 70px;background:linear-gradient(150deg,rgba(29,28,53,.96),rgba(72,45,105,.88));z-index:3;display:flex;flex-direction:column;justify-content:flex-end;animation:mc-float 7s ease-in-out infinite}.mc-preview-main strong{font-size:86px;line-height:.9}.mc-preview-main h3{font-family:var(--mc-display);font-size:35px;font-weight:500;letter-spacing:-.04em;margin:8px 0 26px}.mc-preview-main p{font-size:14px;line-height:1.55;color:#d8d1e5}.mc-preview-progress{display:flex;gap:5px;margin-bottom:22px}.mc-preview-progress i{height:3px;flex:1;background:rgba(255,255,255,.22);border-radius:9px}.mc-preview-progress i:first-child,.mc-preview-progress i:nth-child(2){background:#fff}.mc-preview-streak{width:190px;left:0;top:25px;background:rgba(255,253,248,.96);color:#241d28;z-index:4;transform:rotate(-7deg);animation:mc-float-left 8s ease-in-out infinite}.mc-preview-streak strong{display:block;font-size:58px}.mc-preview-vibe{width:190px;right:-10px;top:0;background:linear-gradient(145deg,#ffdcc8,#ffb897);color:#3b1f1b;z-index:5;transform:rotate(7deg);animation:mc-float-right 7.5s ease-in-out infinite}.mc-preview-vibe strong{display:block;font-size:58px}.mc-preview-hour{width:180px;right:-18px;bottom:28px;background:#09