@keyframes mc-float{0%,100%{transform:translateY(0) rotateY(-4deg)}50%{transform:translateY(-12px) rotateY(-1deg)}}@keyframes mc-float-left{0%,100%{transform:translateY(0) rotate(-7deg)}50%{transform:translateY(10px) rotate(-5deg)}}@keyframes mc-float-right{0%,100%{transform:translateY(0) rotate(7deg)}50%{transform:translateY(-9px) rotate(5deg)}}

/* Promise / sections */
.mc-promise-strip{position:relative;z-index:3;margin-top:-26px;background:rgba(255,253,248,.92);border:1px solid rgba(255,255,255,.8);box-shadow:var(--mc-shadow);border-radius:28px;padding:12px;display:grid;grid-template-columns:repeat(5,1fr);backdrop-filter:blur(20px)}.mc-promise-strip article{display:flex;gap:11px;padding:15px 14px;border-right:1px solid var(--mc-line)}.mc-promise-strip article:last-child{border-right:0}.mc-promise-strip article>span{width:30px;height:30px;border-radius:10px;background:#eee8ff;display:grid;place-items:center;color:#6d56bd;flex:none}.mc-promise-strip strong,.mc-promise-strip small{display:block}.mc-promise-strip strong{font-size:12px}.mc-promise-strip small{font-size:10px;line-height:1.45;color:var(--mc-muted);margin-top:3px}
.section.mc-story-preview,.section.mc-how,.section.mc-privacy-feature{padding:108px 0}.mc-section-heading{max-width:760px}.mc-section-heading h2{font-family:var(--mc-display);font-weight:500;font-size:clamp(46px,6vw,78px);line-height:.98;letter-spacing:-.055em;margin:20px 0}.mc-section-heading h2 em{color:#735ab3}.mc-section-heading p{font-size:17px;line-height:1.7;color:var(--mc-muted);max-width:650px}.mc-sample-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:18px;margin-top:42px}.mc-sample-chapter{min-height:520px;border-radius:34px;padding:32px;display:flex;flex-direction:column;justify-content:flex-end;box-shadow:var(--mc-shadow);overflow:hidden;position:relative}.mc-sample-chapter:before{content:"";position:absolute;inset:0;background:radial-gradient(circle at 50% 20%,rgba(255,255,255,.14),transparent 30%);pointer-events:none}.mc-sample-chapter small{position:absolute;top:30px;left:30px;text-transform:uppercase;letter-spacing:.14em;font-size:10px;font-weight:850;opacity:.65}.mc-sample-chapter h3{font-family:var(--mc-display);font-weight:500;font-size:43px;line-height:1.02;letter-spacing:-.05em;margin:0 0 14px}.mc-sample-chapter p{line-height:1.5;opacity:.75}.mc-sample-chapter.midnight{background:linear-gradient(145deg,#080a12,#191d32);color:#fff}.mc-sample-chapter.neon{background:radial-gradient(circle at 50% 15%,rgba(240,171,252,.2),transparent 35%),linear-gradient(145deg,#050008,#210032);color:#fff}.mc-sample-chapter.sunset{background:linear-gradient(145deg,#fff3e4,#ffc9a7 60%,#ff9b93);color:#2b160e}.mc-safe-badge{display:inline-flex;align-self:flex-start;padding:7px 10px;border:1px solid currentColor;border-radius:999px;font-size:10px;text-transform:uppercase;letter-spacing:.08em;opacity:.62;margin-top:18px}
.mc-flow{margin-top:42px;display:grid;grid-template-columns:repeat(6,1fr);border-top:1px solid var(--mc-line);border-bottom:1px solid var(--mc-line)}.mc-flow-step{padding:22px 15px;min-height:112px;border-right:1px solid var(--mc-line);display:flex;flex-direction:column;justify-content:space-between;gap:20px}.mc-flow-step:last-child{border-right:0}.mc-flow-step span{font-family:ui-monospace,monospace;color:#8b8290;font-size:11px}.mc-flow-step strong{font-family:var(--mc-display);font-size:20px;font-weight:500}.mc-flow.compact{margin:40px auto 0;max-width:960px}.mc-flow.compact .mc-flow-step{min-height:88px;padding:16px 12px}.mc-flow.compact .mc-flow-step strong{font-size:15px}
.mc-privacy-feature{display:grid;grid-template-columns:.9fr 1.1fr;gap:70px;align-items:center}.mc-privacy-receipt{background:#0b0e17;color:#e8e8ef;border-radius:34px;padding:30px;box-shadow:var(--mc-shadow)}.mc-privacy-receipt>div{display:flex;flex-wrap:wrap;gap:8px;align-items:center;font-family:ui-monospace,monospace;font-size:11px;color:#b5f6dd}.mc-privacy-receipt>div span{background:#151a28;border:1px solid rgba(255,255,255,.08);padding:8px 10px;border-radius:9px}.mc-privacy-receipt dl{margin:28px 0 0;display:grid;gap:0}.mc-privacy-receipt dl div{display:flex;justify-content:space-between;gap:20px;padding:14px 0;border-top:1px solid rgba(255,255,255,.09)}.mc-privacy-receipt dt{color:#8e93a5}.mc-privacy-receipt dd{margin:0;font-weight:800}

/* Create / import */
.mc-create-page{position:relative;background:radial-gradient(circle at 50% 0%,rgba(167,139,250,.1),transparent 32%)}.mc-create-head{padding-top:70px;text-align:center;max-width:1060px}.mc-create-head .mc-eyebrow{color:#5d5766;background:rgba(255,255,255,.65);border-color:var(--mc-line)}.mc-create-head h1{font-family:var(--mc-display);font-weight:500;font-size:clamp(56px,7vw,92px);letter-spacing:-.06em;line-height:.92;margin:22px 0}.mc-create-head h1 em{color:#745bb4}.mc-create-head>p{max-width:720px;margin:0 auto;color:var(--mc-muted);font-size:18px;line-height:1.7}.mc-uploader{max-width:980px;margin:42px auto 0;border-radius:38px;background:rgba(255,253,248,.88);padding:16px;border:1px solid rgba(255,255,255,.9);box-shadow:0 30px 100px rgba(52,41,68,.14);backdrop-filter:blur(22px)}.mc-drop{position:relative;overflow:hidden;padding:70px 30px 56px;border-radius:30px;border:1.5px dashed rgba(98,82,125,.3);background:radial-gradient(circle at 50% 30%,rgba(167,139,250,.08),transparent 34%),linear-gradient(180deg,#fffdfa,#faf5ee);transition:border-color .2s ease,transform .2s ease,box-shadow .2s ease}.mc-drop.active{transform:scale(1.006);border-color:#8b5cf6;box-shadow:inset 0 0 0 4px rgba(139,92,246,.06)}.mc-drop-orb{width:78px;height:78px;border-radius:26px;margin:0 auto 18px;display:grid;place-items:center;background:linear-gradient(145deg,#111426,#262342);color:#fff;box-shadow:0 16px 35px rgba(17,20,38,.2)}.mc-drop-orb span{font-size:30px}.mc-drop-label{text-transform:uppercase;letter-spacing:.16em;font-size:10px;font-weight:900;color:#82778e}.mc-drop h2{font-family:var(--mc-display);font-weight:500;font-size:clamp(34px,4vw,52px);letter-spacing:-.045em;margin:12px 0}.mc-drop p{max-width:620px;margin:0 auto 24px;line-height:1.65}.mc-upload-button{min-width:205px}.mc-file-types{display:block;margin-top:14px;color:#8d8592;font-family:ui-monospace,monospace;font-size:10px}.mc-create-controls{padding:16px 8px 5px;align-items:end}.mc-create-controls label{display:grid;gap:6px;color:#6c6572;font-size:11px;font-weight:850;text-transform:uppercase;letter-spacing:.08em}.mc-create-controls .select{min-width:190px;text-transform:none;letter-spacing:0}.mc-upload-receipt{display:flex;gap:10px 22px;flex-wrap:wrap;margin:18px 8px 5px;padding-top:16px;border-top:1px solid var(--mc-line);font-size:11px;color:#6d6671;font-weight:750}.mc-upload-receipt span:before{color:#34a77d}
.mc-processing{margin:14px 4px 0;padding:22px;border-radius:24px;background:#0c0f18;color:#f5f5f8}.mc-processing-head{display:grid;grid-template-columns:auto 1fr auto;align-items:center;gap:14px}.mc-processing-head small{display:block;color:#888ea2;text-transform:uppercase;letter-spacing:.12em;font-size:9px;font-weight:850}.mc-processing-head strong{display:block;margin-top:5px;font-size:17px}.mc-processing-pulse{width:13px;height:13px;border-radius:50%;background:#74e0b7;box-shadow:0 0 0 6px rgba(116,224,183,.1);animation:mc-pulse 1.6s ease-in-out infinite}.mc-processing-percent{font-family:ui-monospace,monospace;color:#b9c0d3}.mc-processing-track{display:flex;gap:5px;margin:20px 0 14px}.mc-processing-track i{height:4px;flex:1;background:#262a36;border-radius:8px;transition:background .2s ease}.mc-processing-track i.active{background:linear-gradient(90deg,#a78bfa,#38bdf8)}.mc-processing-meta{display:flex;flex-wrap:wrap;gap:8px 14px;color:#83899b;font-size:10px}.mc-cancel-row{display:flex;justify-content:center;margin-top:12px}@keyframes mc-pulse{0%,100%{transform:scale(.9);opacity:.75}50%{transform:scale(1.1);opacity:1}}
.mc-ready-bar{margin-top:0!important;background:#10131d;color:#f4f4f7;border-radius:18px;padding:13px 16px;display:flex;justify-content:space-between;align-items:center}.mc-ready-bar>div{display:flex;align-items:center;gap:9px;font-weight:800}.mc-ready-dot{width:9px;height:9px;border-radius:50%;background:#66daa9;box-shadow:0 0 0 5px rgba(102,218,169,.11)}

/* Wrapped results — editorial, not dashboard */
.mc-results{padding-top:44px}.mc-results>.story+.story{margin-top:18px}.mc-results .story-hero{position:relative;overflow:hidden;min-height:670px;border-radius:46px;padding:58px;background:radial-gradient(circle at 85% 16%,rgba(167,139,250,.28),transparent 25%),radial-gradient(circle at 16% 82%,rgba(56,189,248,.14),transparent 26%),linear-gradient(145deg,#070811,#111426 60%,#231d38);box-shadow:0 36px 100px rgba(20,16,34,.24)}.mc-results .story-hero:after{content:"";position:absolute;inset:0;background-image:linear-gradient(rgba(255,255,255,.025) 1px,transparent 1px),linear-gradient(90deg,rgba(255,255,255,.025) 1px,transparent 1px);background-size:42px 42px;mask-image:linear-gradient(180deg,#000,transparent 70%)}.mc-results .story-hero>div,.mc-results .story-hero>p{position:relative;z-index:1}.mc-results .story-hero small{font-size:10px}.mc-results .story-hero h2{font-family:var(--mc-display);font-weight:500;font-size:clamp(58px,8vw,108px);letter-spacing:-.065em;max-width:850px}.mc-results .story-hero p{font-family:ui-monospace,monospace;font-size:12px;color:#a8a9bb}.mc-results .story-summary{margin-top:22px;padding:36px;border-radius:30px;background:#fffaf2;border:0;border-left:6px solid #a78bfa;box-shadow:0 18px 55px rgba(47,38,57,.07)}.mc-results .story-summary strong{font-family:var(--mc-display);font-weight:500;font-size:clamp(36px,5vw,62px);letter-spacing:-.045em}.mc-results .story-summary p{font-size:16px;max-width:720px}
.mc-results .story-grid{display:grid;grid-template-columns:repeat(12,minmax(0,1fr));gap:16px;margin-top:18px}.mc-results .story-card{grid-column:span 6;min-height:235px;border:1px solid rgba(35,30,40,.08);border-radius:30px;padding:28px;background:rgba(255,253,248,.9);box-shadow:0 12px 36px rgba(44,36,54,.055);display:flex;flex-direction:column;justify-content:space-between;transition:transform .2s ease,box-shadow .2s ease}.mc-results .story-card:hover{transform:translateY(-3px);box-shadow:0 20px 48px rgba(44,36,54,.09)}.mc-results .story-card.wide{grid-column:1/-1;min-height:auto}.mc-results .story-card h3{font-size:10px;letter-spacing:.14em}.mc-results .story-number{font-family:var(--mc-display);font-weight:500;font-size:72px;line-height:.95}.mc-results .story-number-date{font-size:50px}.mc-results .story-sub{line-height:1.55}.mc-results .bar-track{background:#eee9e1}.mc-results .bar-fill{background:linear-gradient(90deg,#7c5be7,#d55b91)}.mc-results .vibes{grid-template-columns:repeat(4,1fr)}.mc-results .vibe{min-height:140px;border-radius:24px;background:linear-gradient(160deg,#f6f0ff,#fffaf6);display:flex;flex-direction:column;justify-content:flex-end}.mc-results .vibe strong{font-family:var(--mc-display);font-size:54px;font-weight:500}.mc-results .timeline{min-height:210px;padding-top:25px}.mc-results .year-bar{background:linear-gradient(180deg,#d56e9a,#745bd2)}.mc-results .word{background:#f1ebe3;border-color:#e7ded4;font-size:13px}

/* Flagship chapter deck */
.mc-results .chapter-deck,.chapter-deck{margin-top:72px;padding:34px;border-radius:38px;background:#0b0d16;color:#fff;box-shadow:0 34px 100px rgba(20,16,34,.2)}.chapter-deck .chapter-head{align-items:flex-start}.chapter-deck .chapter-head p{color:#9396a7}.chapter-deck .story-summary-kicker{color:#9f91c7}.chapter-export-controls{padding:12px;border-radius:22px;background:rgba(255,255,255,.055);border:1px solid rgba(255,255,255,.08)}.chapter-export-controls label{color:#aaaebe}.chapter-export-controls .select{background:#151824;color:#fff;border-color:rgba(255,255,255,.1)}.chapter-export-controls .btn-soft{background:#151824;color:#fff;border-color:rgba(255,255,255,.1)}.chapter-preview{min-height:680px;border-radius:32px;padding:64px;box-shadow:0 30px 80px rgba(0,0,0,.32);position:relative;overflow:hidden}.chapter-preview:after{content:"";position:absolute;inset:0;pointer-events:none;box-shadow:inset 0 0 0 1px rgba(255,255,255,.09);border-radius:inherit}.chapter-preview small,.chapter-preview h3,.chapter-preview strong,.chapter-preview span,.chapter-preview p,.chapter-preview .chapter-privacy{position:relative;z-index:1}.chapter-preview h3{font-family:var(--mc-display);font-weight:500;letter-spacing:-.055em;max-width:760px}.chapter-preview strong{font-family:var(--mc-display);font-weight:500}.chapter-privacy{display:inline-flex;align-self:center;padding:8px 11px;border:1px solid currentColor;border-radius:999px;opacity:.56}.chapter-nav{padding:10px 0 0}.chapter-deck .chapter-nav .btn-soft{color:#fff;background:#161924;border-color:rgba(255,255,255,.1)}.chapter-dots button{background:rgba(255,255,255,.2)}.chapter-dots button.active{background:#fff}

/* Cinematic */
.mc-cinematic{margin-top:22px!important;padding:34px!important;border-radius:38px!important;background:linear-gradient(145deg,#fffdf8,#eee7dc)!important;border:1px solid rgba(255,255,255,.9)!important;box-shadow:0 25px 75px rgba(46,37,55,.1)}.mc-cinematic-head{align-items:center}.mc-local-chip{padding:8px 11px;border-radius:999px;background:#e8f6ef;color:#31755b;font-size:10px;text-transform:uppercase;letter-spacing:.1em;font-weight:850}.mc-cinematic-stage{position:relative;overflow:hidden;min-height:650px!important;max-width:430px!important;border-radius:40px!important;padding:44px 34px!important;isolation:isolate}.mc-cinematic-stage:fullscreen{max-width:none!important;width:100vw;height:100vh;border-radius:0!important;margin:0!important}.mc-cinematic-copy{position:relative;z-index:2;display:flex;flex-direction:column;align-items:center;justify-content:center;flex:1}.mc-cinematic-copy h3{font-family:var(--mc-display);font-weight:500;font-size:44px!important;letter-spacing:-.045em}.mc-cinematic-copy strong{font-family:var(--mc-display);font-weight:500}.mc-film-grain{position:absolute;inset:0;z-index:1;opacity:.1;background-image:url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.9' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.28'/%3E%3C/svg%3E");pointer-events:none}.mc-cinematic-controls{justify-content:center;margin-top:20px}.theme-motion-midnight .mc-cinematic-copy{animation:mc-soft-reveal .55s ease}.theme-motion-sunset .mc-cinematic-copy{animation:mc-film-dissolve .6s ease}.theme-motion-paper .mc-cinematic-copy{animation:mc-paper-slide .55s ease}.theme-motion-neon .mc-cinematic-copy{animation:mc-neon-pulse .5s ease}@keyframes mc-soft-reveal{from{opacity:0;transform:scale(.985)}to{opacity:1;transform:none}}@keyframes mc-film-dissolve{from{opacity:.2;filter:blur(4px)}to{opacity:1;filter:none}}@keyframes mc-paper-slide{from{opacity:0;transform:translateX(12px) rotate(.3deg)}to{opacity:1;transform:none}}@keyframes mc-neon-pulse{from{opacity:.35;transform:translateY(8px)}to{opacity:1;transform:none}}

/* Share / premium / keepsake / optional services */
.share-panel,.premium-panel,.keepsake-panel,.ai-panel,.cloud-panel,.local-lore-panel{margin-top:22px!important;border-radius:30px!important;background:rgba(255,253,248,.93)!important;border:1px solid rgba(35,30,40,.08)!important;box-shadow:0 16px 45px rgba(43,35,52,.06)}.share-panel{padding:30px!important}.share-panel h3,.premium-panel h3,.keepsake-panel h3,.ai-panel h3{font-family:var(--mc-display);font-size:30px;letter-spacing:-.035em}.toggle{padding:10px 12px;background:#f4eee7;border-radius:14px}.share-input,.select,.story-textarea{background:#fffdf9;border-color:rgba(35,30,40,.12)!important}.print-preview{border-radius:26px!important;overflow:hidden}.print-cover{background:linear-gradient(145deg,#f7f1e8,#efe2cf)!important;color:#241c15!important;box-shadow:inset 0 0 0 1px rgba(139,94,52,.12)}

