import { AccountShell } from "@/components/AccountShell";
import { WorldMediaUploader } from "@/components/WorldMediaUploader";
import { getStorySession } from "@/platform/identity/session";
import { supabaseRest, supabaseStorageSignedUrl } from "@/platform/persistence/supabase-rest";
import { worldProductLabels, isWorldProduct } from "@/platform/worlds/catalog";
export const dynamic="force-dynamic";
export default async function WorldPage({params}:{params:Promise<{id:string}>}){
 const s=await getStorySession();if(!s)redirect("/login");const{id}=await params;if(!/^[0-9a-f-]{36}$/i.test(id))notFound();
 const worlds=await supabaseRest<Array<{id:string;product:string;title:string;summary?:string|null;anchor_date?:string|null}>>("worlds?id=eq."+id+"&select=id,product,title,summary,anchor_date&limit=1",s.token);const world=worlds[0];if(!world)notFound();
 const [events,mediaRows,albums,links]=await Promise.all([
  supabaseRest<Array<{id:string;event_type:string;occurred_at:string;title:string;description?:string|null;location?:string|null}>>("story_events?world_id=eq."+id+"&select=id,event_type,occurred_at,title,description,location&order=occurred_at.desc&limit=200",s.token),
  supabaseRest<Array<{id:string;object_path:string;media_kind:string;caption?:string|null}>>("media_assets?world_id=eq."+id+"&select=id,object_path,media_kind,caption&order=created_at.desc&limit=48",s.token),
  supabaseRest<Array<{id:string;title:string;description?:string|null}>>("albums?world_id=eq."+id+"&select=id,title,description&order=updated_at.desc&limit=24",s.token),
  supabaseRest<Array<{track_id:string;position:number}>>("world_music_tracks?world_id=eq."+id+"&select=track_id,position&order=position.asc",s.token)
 ]);
 const media=await Promise.all(mediaRows.map(async(row)=>({...row,signedUrl:await supabaseStorageSignedUrl(row.object_path,s.token).catch(()=>null)})));
 const ids=links.map(x=>x.track_id);const tracks=ids.length?await supabaseRest<Array<{id:string;title:string;artist?:string|null;external_url?:string|null}>>("music_tracks?id=in.("+ids.join(",")+")&select=id,title,artist,external_url",s.token):[];
 const label=isWorldProduct(world.product)?worldProductLabels[world.product]:world.product;
 return <AccountShell email={s.user.email}><div className="saas-page"><section className="world-cover"><small>{label}{world.anchor_date?" · "+world.anchor_date:""}</small><h1>{world.title}</h1><p>{world.summary||"A private world built from the memories you choose."}</p></section>
 <section className="saas-section"><div className="saas-section-head"><div><span className="story-summary-kicker">Private media</span><h2>Pictures make the world breathe</h2></div></div><WorldMediaUploader worldId={id}/>{media.length?<div className="media-grid">{media.map(row=><article className="media-tile" key={row.id}>{row.media_kind==="image"&&row.signedUrl?<img src={row.signedUrl} alt={row.caption||"Private world memory"} loading="lazy"/>:row.media_kind==="video"&&row.signedUrl?<video src={row.signedUrl} controls preload="metadata"/>:<div className="record-disc">♪</div>}</article>)}</div>:null}</section>
 <section className="saas-section"><div className="saas-section-head"><div><span className="story-summary-kicker">Timeline</span><h2>The life of this world</h2></div></div>{events.length?<div className="memory-timeline">{events.map(event=><article key={event.id}><small>{event.occurred_at.slice(0,10)} · {event.event_type}{event.location?" · "+event.location:""}</small><h3>{event.title}</h3>{event.description?<p>{event.description}</p>:null}</article>)}</div>:<div className="saas-empty">Memories saved from the local builder will appear here after you explicitly save them to your account.</div>}</section>
 <section className="saas-section"><div className="saas-section-head"><div><span className="story-summary-kicker">Albums</span><h2>Curated chapters</h2></div><Link href="/albums">Create an album →</Link></div>{albums.length?<div className="album-shelf">{albums.map(album=><Link className="album-card world-card" href={"/albums/"+album.id} key={album.id}><small>Album</small><strong>{album.title}</strong><span>{album.description||"Open the visual story"}</span></Link>)}</div>:<div className="saas-empty">Turn selected photos and videos into an album with its own cover and soundtrack.</div>}</section>
 {tracks.length?<section className="soundtrack"><span className="story-summary-kicker">World soundtrack</span><h2>Songs attached to this memory space</h2>{tracks.map(track=><article key={track.id}><div className="record-disc">♪</div><div><strong>{track.title}</strong><p>{track.artist||"Personal soundtrack"}</p>{track.external_url?<a href={track.external_url} target="_blank" rel="noreferrer">Official link ↗</a>:null}</div></article>)}</section>:null}</div></AccountShell>;
}

"use client";import{useState}from"react";
const products=[["myyear","MyYear"],["petlife","PetLife"],["relationship","Relationship"],["lifemap","LifeMap"],["babystory","BabyStory"],["homestory","HomeStory"],["familytree","FamilyTree"],["founderworld","FounderWorld"],["creatorworld","CreatorWorld"]]as const;
export function AccountDashboardClient(){const[open,setOpen]=useState(false),[message,setMessage]=useState("");async function create(form:FormData){setMessage("Creating your world…");const r=await fetch("/api/worlds",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({product:form.get("product"),title:form.get("title")})});const d=await r.json();if(!r.ok){setMessage(d.error??"Could not create world.");return;}window.location.href=`/worlds/${d.world.id}`;}return <div className="saas-create"><button className="btn btn-primary" onClick={()=>setOpen(v=>!v)}>{open?"Close":"Create a memory world"}</button>{open?<form action={create} className="saas-create-form"><label>World type<select name="product" className="select">{products.map(([v,l])=><option value={v} key={v}>{l}</option>)}</select></label><label>Title<input name="title" required maxLength={160} className="share-input" placeholder="My 2026, Milo, Our story…"/></label><button className="btn btn-primary">Create world</button></form>:null}{message?<p role="status" className="notice">{message}</p>:null}</div>}

"use client";

import { useEffect, useMemo, useState } from "react";
import type { ChatStats, StoryMode } from "@/lib/types";
import { STORY_ENRICHMENT_INTENTS, type StoryEnrichmentIntent } from "@/platform/ai/types";
import { composeThreadTale } from "@/platform/story/compose";
import { trackProductEvent } from "@/platform/telemetry/client";

const ACTIONS: Array<{ intent: StoryEnrichmentIntent; label: string }> = [
  { intent: "sweeter", label: "Make this caption sweeter" },
  { intent: "funnier", label: "Make this chapter funnier" },
  { intent: "birthday-caption", label: "Write a birthday caption" },
  { intent: "anniversary-caption", label: "Write an anniversary caption" },
  { intent: "shorter-share-caption", label: "Make this share caption shorter" },
];

export function AIEnrichmentPanel({ stats, mode }: { stats: ChatStats; mode: StoryMode }) {
  const [enabled, setEnabled] = useState<boolean | null>(null);
  const [intent, setIntent] = useState<StoryEnrichmentIntent>("recap");
  const [snippet, setSnippet] = useState("");
  const [consent, setConsent] = useState(false);
  const [output, setOutput] = useState("");
  const [message, setMessage] = useState("");
  const [busy, setBusy] = useState(false);

  const safeChapters = useMemo(() => composeThreadTale(stats, mode).filter((chapter) => chapter.privacyLevel === "safe").map(({ id, type, title, subtitle, metric, supportingText, renderVariant }) => ({ id, type, title, subtitle, metric, supportingText, renderVariant })), [stats, mode]);

  useEffect(() => {
    let cancelled = false;
    void fetch("/api/ai/enrich", { cache: "no-store" }).then((response) => response.json()).then((data: { enabled?: boolean }) => { if (!cancelled) setEnabled(Boolean(data.enabled)); }).catch(() => { if (!cancelled) setEnabled(false); });
    return () => { cancelled = true; };
  }, []);

  async function enrich(nextIntent = intent) {
    if (!STORY_ENRICHMENT_INTENTS.includes(nextIntent)) return;
    setIntent(nextIntent); setBusy(true); setMessage("");
    trackProductEvent("ai_enrichment_started", "threadtales", mode);
    try {
      const input = {
        product: "threadtales" as const,
        mode,
        intent: nextIntent,
        facts: {
          totalMessages: stats.totalMessages, totalWords: stats.totalWords, daysTogether: stats.daysTogether, activeDays: stats.activeDays,
          longestStreak: stats.longestStreak, longestSilenceDays: stats.longestSilenceDays, medianReplyMinutes: stats.medianReplyMinutes,
          peakHour: stats.peakHour, favoriteWeekday: stats.favoriteWeekday, lateNightMessages: stats.lateNightMessages,
          questionsAsked: stats.questionsAsked, laughSignals: stats.laughSignals, heartSignals: stats.heartSignals, mediaSignals: stats.mediaSignals,
          conversationBalance: stats.conversationBalance, yearCount: stats.byYear.length,
        },
        chapters: safeChapters,
        ...(snippet.trim() ? { selectedSnippet: snippet.trim(), snippetConsent: consent } : {}),
      };
      const response = await fetch("/api/ai/enrich", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(input) });
      const data = await response.json() as { text?: string; error?: string; model?: string };
      if (!response.ok || !data.text) throw new Error(data.error ?? "AI enrichment failed.");
      setOutput(data.text); trackProductEvent("ai_enrichment_completed", "threadtales", mode);
      setMessage(`Optional AI copy generated${data.model ? ` with ${data.model}` : ""}. Edit it freely before using it.`);
    } catch (cause) { setMessage(cause instanceof Error ? cause.message : "AI enrichment failed."); }
    finally { setBusy(false); }
  }

  if (enabled === null) return <section className="story ai-panel"><p>Checking optional AI enrichment…</p></section>;
  if (!enabled) return <section className="story ai-panel mc-ai-panel"><span className="story-summary-kicker">Optional AI</span><h3>Deterministic story mode is active.</h3><p>AI enrichment is not configured. The analysis, story, sharing and exports continue without it.</p><div className="mc-ai-safety">AI only uses the share-safe summary unless you explicitly allow a selected snippet.</div></section>;

  return <section className="story ai-panel mc-ai-panel">
    <span className="story-summary-kicker">Optional AI studio</span><h3>Polish the words, not the facts.</h3>
    <p>These actions send only allowlisted aggregate metrics and share-safe deterministic chapters by default. Participant names, top words and raw messages stay out.</p>
    <div className="mc-ai-actions" aria-label="AI writing actions">{ACTIONS.map((action) => <button className={`btn btn-soft ${intent === action.intent ? "active" : ""}`} key={action.intent} disabled={busy || Boolean(snippet.trim() && !consent)} onClick={() => void enrich(action.intent)}>{action.label}</button>)}</div>
    <label className="file-drop">Optional user-selected snippet<textarea className="share-input story-textarea" value={snippet} maxLength={600} onChange={(event) => { setSnippet(event.target.value); if (!event.target.value.trim()) setConsent(false); }} placeholder="Paste up to 600 characters only if you want this exact snippet processed remotely."/></label>
    {snippet.trim() ? <label className="toggle"><input type="checkbox" checked={consent} onChange={(event)=>setConsent(event.target.checked)}/> I understand this selected snippet will be sent to the configured AI provider.</label> : null}
    <div className="mc-ai-safety">AI only uses the share-safe summary unless you explicitly allow more context.</div>
    <button className="btn btn-primary" disabled={busy || Boolean(snippet.trim() && !consent)} onClick={() => void enrich("recap")}>{busy ? "Writing…" : "Generate full recap copy"}</button>
    {output ? <label className="file-drop">Editable AI output<textarea className="share-input story-textarea ai-output" value={output} onChange={(event)=>setOutput(event.target.value)}/></label> : null}
    {message ? <div className="notice" role="status">{message}</div> : null}
  </section>;
}
